    @Override
    public void update(int waterLevel, String date, String time){
        lblDisplay.setText("Water Level is: "+waterLevel);
        lblDate.setText(date);
        lblTime.setText(time);
        
         if (waterLevel >= 50) {
            btnStatus.setBackground(java.awt.Color.RED);
            btnStatus.setText("HIGH");
        } else {
            btnStatus.setBackground(java.awt.Color.GREEN);
            btnStatus.setText("NORMAL");
        }
    }

